<script setup lang="ts">
import { computed, inject, onMounted, ref } from "vue";
import { Activity, ArrowClockwise, ArrowUpRight, CheckCircle, ClockCountdown, Cpu, Database, Globe, HardDrives, ShieldWarning, Warning } from "@phosphor-icons/vue";
import type { APIClient } from "../api";
import { router } from "../router";
import { sessionStore } from "../store";

interface Metric { label: string; value: string; detail: string; tone?: string }
interface WorkItem { id: string; title: string; detail: string; state: string; route?: string; observed_at?: string }
const api=inject<APIClient>("api")!;const loading=ref(true);const error=ref("");const raw=ref<Record<string,unknown>>({});
const metrics=computed<Metric[]>(()=>{
  const source=record(raw.value.metrics);if(Array.isArray(raw.value.metrics))return raw.value.metrics.filter(isRecord).map((item)=>({label:text(item.label,"Metric"),value:text(item.value,"—"),detail:text(item.detail,""),tone:text(item.tone,"neutral")}));
  return [
    {label:"Sites",value:numberText(source.sites??raw.value.sites),detail:`${numberText(source.active_sites??raw.value.active_sites)} active`,tone:"healthy"},
    {label:"CPU pressure",value:percent(source.cpu_percent??raw.value.cpu_percent),detail:text(source.load,"Current host utilization"),tone:pressureTone(source.cpu_percent)},
    {label:"Memory",value:percent(source.memory_percent??raw.value.memory_percent),detail:bytes(source.memory_used_bytes),tone:pressureTone(source.memory_percent)},
    {label:"Disk",value:percent(source.disk_percent??raw.value.disk_percent),detail:bytes(source.disk_free_bytes,"free"),tone:pressureTone(source.disk_percent)},
    {label:"Backups",value:numberText(source.recovery_points??raw.value.recovery_points),detail:text(source.last_backup,"verified recovery points"),tone:text(source.backup_state,"neutral")},
    {label:"Security",value:numberText(source.open_findings??raw.value.open_findings),detail:"open findings",tone:Number(source.open_findings||0)>0?"warning":"healthy"}
  ];
});
const operations=computed(()=>list(raw.value.operations));const findings=computed(()=>list(raw.value.findings));const services=computed(()=>list(raw.value.services));const activity=computed(()=>list(raw.value.activity));
onMounted(()=>void load());
async function load():Promise<void>{loading.value=true;error.value="";try{if(!api.available("dashboard.summary"))throw new Error("The dashboard projection is not enabled on this node.");const response=await api.invoke<unknown>("dashboard.summary",{tenantId:sessionStore.state.tenantId||undefined,payload:{operation_limit:8,finding_limit:6,activity_limit:12}});raw.value=isRecord(response.result)?response.result:{}}catch(cause){error.value=cause instanceof Error?cause.message:"Dashboard projection failed."}finally{loading.value=false}}
function list(value:unknown):Record<string,unknown>[]{return Array.isArray(value)?value.filter(isRecord):[]}function record(value:unknown):Record<string,unknown>{return isRecord(value)?value:{}}function isRecord(value:unknown):value is Record<string,unknown>{return Boolean(value)&&typeof value==="object"&&!Array.isArray(value)}
function text(value:unknown,fallback="—"):string{return value===undefined||value===null||value===""?fallback:String(value)}function numberText(value:unknown):string{return new Intl.NumberFormat().format(Number(value)||0)}function percent(value:unknown):string{return `${Math.round(Number(value)||0)}%`}function bytes(value:unknown,suffix="used"):string{const n=Number(value);if(!Number.isFinite(n)||n<=0)return suffix;const units=["B","KiB","MiB","GiB","TiB","PiB"];let v=n;let i=0;while(v>=1024&&i<units.length-1){v/=1024;i++}return`${v>=10?v.toFixed(0):v.toFixed(1)} ${units[i]} ${suffix}`}function pressureTone(value:unknown):string{const n=Number(value)||0;return n>=90?"critical":n>=75?"warning":"healthy"}function route(path:string):void{router.push(path)}
const iconFor=(index:number)=>[Globe,Cpu,Database,HardDrives,ClockCountdown,ShieldWarning][index]||Activity;
</script>

<template>
  <main class="dashboard">
    <header class="dashboard-head"><div><p class="eyebrow">NODE / LIVE PROJECTION</p><h2>Operational overview</h2><p>Control state, host pressure, unfinished work, and risk in one bounded view.</p></div><button class="button button-small" type="button" :disabled="loading" @click="load"><ArrowClockwise :size="15" :class="{spinning:loading}"/>Refresh</button></header>
    <div v-if="error" class="dashboard-error"><Warning :size="18"/>{{error}}</div>
    <section class="metrics" :aria-busy="loading">
      <article v-for="(metric,index) in metrics" :key="metric.label" class="metric"><div class="metric-icon" :class="`tone-${metric.tone}`"><component :is="iconFor(index)" :size="18"/></div><div><p>{{metric.label}}</p><strong>{{loading?'—':metric.value}}</strong><span>{{loading?'Loading projection':metric.detail}}</span></div></article>
    </section>
    <div class="dashboard-grid">
      <section class="panel operations-panel"><header><div><p>WORKFLOW ENGINE</p><h3>Unfinished operations</h3></div><button type="button" @click="route('/audit')">All activity<ArrowUpRight :size="14"/></button></header><div v-if="loading" class="panel-loading"><span v-for="i in 5" :key="i" class="skeleton"></span></div><div v-else-if="!operations.length" class="inline-empty"><CheckCircle :size="25"/><div><strong>No unfinished work</strong><span>Every admitted operation has reached a terminal record.</span></div></div><div v-else class="operation-list"><article v-for="item in operations" :key="text(item.id)"><i :class="`state-${text(item.state,'pending')}`"></i><div><strong>{{text(item.title||item.operation)}}</strong><span>{{text(item.resource||item.detail)}}</span></div><div><span class="status" :class="`status-${text(item.state).toLowerCase()}`">{{text(item.state)}}</span><small>{{text(item.updated_at)}}</small></div></article></div></section>
      <section class="panel risk-panel"><header><div><p>SECURITY POSTURE</p><h3>Findings requiring attention</h3></div><button type="button" @click="route('/security')">Open posture<ArrowUpRight :size="14"/></button></header><div v-if="loading" class="panel-loading"><span v-for="i in 4" :key="i" class="skeleton"></span></div><div v-else-if="!findings.length" class="inline-empty"><CheckCircle :size="25"/><div><strong>No unresolved findings</strong><span>The latest policy and scan projections are clear.</span></div></div><div v-else class="finding-list"><article v-for="item in findings" :key="text(item.id)"><span :class="`severity-${text(item.severity,'info').toLowerCase()}`">{{text(item.severity,'info')}}</span><div><strong>{{text(item.title||item.kind)}}</strong><small>{{text(item.resource||item.detail)}}</small></div></article></div></section>
      <section class="panel service-panel"><header><div><p>DATA PLANE</p><h3>Managed services</h3></div><button type="button" @click="route('/services')">Diagnostics<ArrowUpRight :size="14"/></button></header><div class="service-grid"><article v-for="item in services.slice(0,8)" :key="text(item.id||item.name)"><span class="status" :class="`status-${text(item.health||item.state).toLowerCase()}`">{{text(item.name)}}</span><small>{{text(item.version||item.detail)}}</small></article><div v-if="!loading&&!services.length" class="inline-empty compact"><Activity :size="22"/><span>No service projection yet.</span></div></div></section>
      <section class="panel activity-panel"><header><div><p>RECENT CONTROL DECISIONS</p><h3>Activity</h3></div><button type="button" @click="route('/audit')">Evidence log<ArrowUpRight :size="14"/></button></header><ol><li v-for="item in activity.slice(0,9)" :key="text(item.id||item.event_id)"><span></span><div><strong>{{text(item.action||item.title)}}</strong><small>{{text(item.actor)}} · {{text(item.resource)}}</small></div><time>{{text(item.occurred_at||item.updated_at)}}</time></li><li v-if="!loading&&!activity.length" class="activity-empty">No control decisions have been projected.</li></ol></section>
    </div>
  </main>
</template>

<style scoped>
.dashboard{padding:34px clamp(18px,3.2vw,48px) 64px;max-width:1700px;margin:0 auto}.dashboard-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:27px}.dashboard-head h2{margin:5px 0 8px;font-size:clamp(29px,3vw,39px);letter-spacing:-.045em;line-height:1}.dashboard-head>div>p:last-child{margin:0;color:var(--muted)}.eyebrow{color:var(--accent);font:10px/1 "Panel Mono",monospace;letter-spacing:.13em;margin:0}.dashboard-error{display:flex;align-items:center;gap:8px;margin:0 0 15px;padding:11px 13px;border-left:3px solid var(--critical);background:color-mix(in srgb,var(--critical),transparent 92%);color:var(--critical)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));border:1px solid var(--border);background:var(--border);gap:1px;margin-bottom:18px}.metric{min-height:126px;background:var(--surface);padding:16px;display:flex;gap:13px}.metric-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:7px;background:var(--surface-2);color:var(--subtle);flex:0 0 auto}.tone-healthy{color:var(--healthy);background:color-mix(in srgb,var(--healthy),transparent 91%)}.tone-warning{color:var(--warning);background:color-mix(in srgb,var(--warning),transparent 91%)}.tone-critical{color:var(--critical);background:color-mix(in srgb,var(--critical),transparent 91%)}.metric p{margin:1px 0 8px;color:var(--muted);font-size:11px}.metric strong{display:block;font:23px/1 "Panel Mono",monospace;letter-spacing:-.04em}.metric span{display:block;margin-top:9px;color:var(--subtle);font-size:10px}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:18px}.panel{border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);min-width:0}.panel>header{min-height:68px;padding:14px 17px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}.panel header p{margin:0 0 6px;color:var(--subtle);font:9px/1 "Panel Mono",monospace;letter-spacing:.12em}.panel header h3{margin:0;font-size:15px}.panel header button{border:0;background:transparent;color:var(--accent);display:flex;align-items:center;gap:6px;cursor:pointer;font-size:11px}.operation-list article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border)}.operation-list article:last-child{border:0}.operation-list i{width:8px;height:8px;border-radius:50%;background:var(--info)}.operation-list div{display:grid;gap:4px;min-width:0}.operation-list strong{font-size:12px;overflow:hidden;text-overflow:ellipsis}.operation-list span,.operation-list small{color:var(--subtle);font-size:10px}.operation-list div:last-child{justify-items:end}.finding-list article{display:grid;grid-template-columns:70px 1fr;gap:10px;padding:13px 16px;border-bottom:1px solid var(--border)}.finding-list article:last-child{border:0}.finding-list>article>span{font:9px/1 "Panel Mono",monospace;text-transform:uppercase;color:var(--subtle);padding-top:3px}.finding-list .severity-critical{color:var(--critical)}.finding-list .severity-high,.finding-list .severity-warning{color:var(--warning)}.finding-list div{display:grid;gap:5px}.finding-list strong{font-size:12px}.finding-list small{color:var(--subtle)}.service-grid{display:grid;grid-template-columns:repeat(2,1fr)}.service-grid article{min-height:63px;padding:13px 16px;border-bottom:1px solid var(--border);display:grid;gap:7px}.service-grid article:nth-child(odd){border-right:1px solid var(--border)}.service-grid small{color:var(--subtle);overflow:hidden;text-overflow:ellipsis}.activity-panel ol{list-style:none;margin:0;padding:9px 16px 15px}.activity-panel li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:start;padding:9px 0}.activity-panel li>span{width:6px;height:6px;margin-top:5px;border-radius:50%;background:var(--accent)}.activity-panel li div{display:grid;gap:4px}.activity-panel li strong{font-size:11px}.activity-panel li small,.activity-panel time{color:var(--subtle);font-size:9px}.inline-empty{min-height:130px;display:flex;justify-content:center;align-items:center;gap:11px;color:var(--healthy);padding:25px}.inline-empty div{display:grid;gap:5px}.inline-empty span{color:var(--subtle);font-size:11px}.inline-empty.compact{grid-column:1/-1;min-height:110px;color:var(--subtle)}.panel-loading{display:grid;gap:1px;padding:15px}.panel-loading .skeleton{height:36px}.activity-empty{color:var(--subtle);justify-content:center!important}.spinning{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(1turn)}}
@media(max-width:1250px){.metrics{grid-template-columns:repeat(3,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:700px){.dashboard{padding:23px 14px 50px}.dashboard-head{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr)}.metric{min-height:112px;padding:13px}.activity-panel time{display:none}}
</style>
